def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    desperate_opp = False
    rich_opp = False
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) > budget * 1.2:
                rich_opp = True
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_opp = True
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 18.0 if hp > 4 else 45.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17.0
    supply_loose = supply >= 22.0
    critical = hp <= 2 or no_water >= 2
    urgent = hp <= 4 or no_water >= 1
    late_game = day >= 8

    if critical:
        bid = max(72.0, highest_prev + 3.0)
        if supply_tight:
            bid += 8.0
        return float(min(budget, bid))

    if urgent:
        if highest_prev >= 110.0:
            bid = 62.0 if not supply_tight else 78.0
        else:
            bid = max(52.0, min(88.0, highest_prev + 2.5))
        if desperate_opp and supply_tight:
            bid += 6.0
        return float(min(budget, bid))

    if supply_loose and hp >= 6 and no_water == 0:
        return float(min(budget, 12.0))

    if highest_prev >= 120.0:
        bid = 16.0 if hp >= 7 else 34.0
    elif highest_prev >= 90.0:
        bid = 22.0 if hp >= 7 else 40.0
    else:
        bid = max(24.0, min(60.0, avg_prev * 0.55 + 3.0))

    if supply_tight:
        bid += 8.0
    if rich_opp and not urgent:
        bid -= 4.0
    if late_game and hp <= 5:
        bid += 10.0

    reserve_floor = DAILY_SALARY * max(0, 10 - day)
    if budget > reserve_floor + 120:
        bid += 4.0

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
    if prev_bids:
        target = max(prev_bids) + 3.0
    else:
        supply = day_context['supply']
        target = DAILY_SALARY * (WATER_REQ / supply) * 1.2
    # adjust for hp
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    if hp <= 2 or no_water > 0:
        target *= 1.3
    elif hp > 5:
        target *= 0.85
    # supply scaling
    target *= 1.0 + (1.0 - (day_context['supply'] / 25.0)) * 0.2
    # clamp
    target = max(10.0, min(my_status['budget'], target))
    # ensure integer index safety
    return int(target) if target <= my_status['budget'] else my_status['budget']
